/**
 * Explanation Formatter for StudyBud
 *
 * Pre-processes Markdown generated by Gemma or provided in study materials
 * before passing to ReactMarkdown.
 *
 * Key Capabilities:
 * 1. Preserves legitimate mathematical notation:
 *    - Inline equations/variables ($F = ma$, $$E = mc^2$$, $P$, $Q_s$)
 *    - Block formulas ($$Q_s = 20 + 2P$$)
 * 2. Preserves currency and ordinary prose:
 *    - $50, $100, $5.99, $1,000, $50M
 *    - Prevents currency from being mispaired as math delimiters
 * 3. Strips stray dollar signs from ordinary prose, headings, and lists:
 *    - ### $1. Core Idea$ -> ### 1. Core Idea
 *    - $Photosynthesis$ -> Photosynthesis
 *    - * $Glucose$ -> * Glucose
 * 4. Normalizes and preserves arrow symbols visually:
 *    - Process chains: Sunlight -> Chlorophyll -> Glucose becomes Sunlight → Chlorophyll → Glucose
 *    - ASCII & heavy arrows (->, -->, ➔) -> →
 *    - Left arrows (<-, <--) -> ←
 *    - LaTeX arrows (\rightarrow, \to, \leftarrow, \uparrow, \downarrow) -> →, ←, ↑, ↓
 *    - Standalone LaTeX arrow blocks ($$\downarrow$$, $$\uparrow$$) -> ↓, ↑
 *    - Process phrases like "A yields B yields C" or "Input arrow Output" -> A → B → C
 * 5. Code safety:
 *    - Code blocks (```...```) and inline code (`...`) are never modified.
 */

// Helper to determine if text enclosed in dollar signs is legitimate mathematical notation
export function isValidMath(content: string): boolean {
  const trimmed = content.trim();
  if (!trimmed) return false;

  // If it contains LaTeX math commands (\frac, \sqrt, \times, \pm, \sum, \int, \Delta, etc.)
  if (/\\[a-zA-Z]+/.test(trimmed)) {
    // If it's ONLY \text{ordinary text with no math}, it's just wrapped prose
    if (/^\\text\{[a-zA-Z\s,.-]+\}$/.test(trimmed)) {
      return false;
    }
    return true;
  }

  // If it contains mathematical operators or relations: =, +, -, *, /, ^, _, <, >, ≤, ≥, ±, ≈, ≠, ÷
  if (/[\^_=+\-*\/<>≤≥±≈≠÷]/.test(trimmed)) {
    return true;
  }

  // Single variable (e.g. $x$, $y$, $P$, $Q$, $m$, $a$, $c$, $v$, $F$)
  // or single variable with subscript/superscript (e.g. $Q_s$, $v_0$, $F_{net}$, $x_1$, $x^2$)
  if (/^[a-zA-Z](?:_[a-zA-Z0-9{}]+|\^[a-zA-Z0-9{}]+)?$/.test(trimmed)) {
    return true;
  }

  // Common scientific or chemical formulas with subscripts/numbers like H2O, CO2, O2, C6H12O6
  if (/^(?:[A-Z][a-z]?\d*)+$/.test(trimmed) && trimmed.length <= 10 && /\d/.test(trimmed)) {
    return true;
  }

  // Otherwise, it is plain words/text wrapped in $ (e.g. $Photosynthesis$, $Core Idea$, $Chlorophyll$, $energy$)
  return false;
}

/**
 * Clean and format explanation text for visual UI display in StudyBud.
 * Does NOT alter spoken text (spoken transformations belong in speechCleaner.ts).
 */
export function formatExplanationForDisplay(raw: string | null | undefined): string {
  if (!raw || typeof raw !== 'string') {
    return '';
  }

  let text = raw;

  // 1. Temporarily protect fenced code blocks and inline code
  const codeBlocks: string[] = [];
  text = text.replace(/```[a-zA-Z0-9_-]*\n?([\s\S]*?)```/g, (match) => {
    codeBlocks.push(match);
    return `__CODE_BLOCK_${codeBlocks.length - 1}__`;
  });

  const inlineCodes: string[] = [];
  text = text.replace(/`([^`]+)`/g, (match) => {
    inlineCodes.push(match);
    return `__INLINE_CODE_${inlineCodes.length - 1}__`;
  });

  // 2. Clean headings wrapped in dollar signs:
  // e.g. "### $1. Core Idea$" -> "### 1. Core Idea"
  // e.g. "# $Photosynthesis$" -> "# Photosynthesis"
  text = text.replace(/^([ \t]*#{1,6}[ \t]+)\$([^\$\n]+)\$[ \t]*$/gm, '$1$2');
  text = text.replace(/^([ \t]*#{1,6}[ \t]+[^\n]*?)\$([a-zA-Z0-9\s.,:;!?]+)\$([^\n]*)$/gm, '$1$2$3');

  // 3. Clean numbered and bullet list items wrapped in dollar signs:
  // e.g. "1. $First step$" -> "1. First step"
  // e.g. "* $Glucose$" -> "* Glucose"
  // e.g. "- $Oxygen$" -> "- Oxygen"
  text = text.replace(/^([ \t]*(?:\d+\.|[-*+])[ \t]+)\$([^\$\n]+)\$[ \t]*$/gm, '$1$2');

  // 4. Temporarily protect Currency figures so they are never treated as math delimiters
  // Matches: $50, $100, $5.99, $1,000, $50M, $10 billion (excluding numbered list indicators like $1. )
  const currencies: string[] = [];
  text = text.replace(
    /(^|[\s(])\$(\d{1,3}(?:,\d{3})*(?:\.\d+)?|\d+(?:\.\d+)?)(?!\.\s*[a-zA-Z])(?:\s*(?:[kKmMbBtT]|billion|million|thousand|trillion|dollars?|cents?|USD))?(?=[.,;!?)]|\s|$)/g,
    (_match, prefix, amount) => {
      currencies.push(`$${amount}`);
      return `${prefix}__CURRENCY_${currencies.length - 1}__`;
    }
  );

  // 5. Normalize LaTeX arrows and standalone arrow math blocks:
  // e.g. $$\downarrow$$ -> ↓, $$\uparrow$$ -> ↑, $$\rightarrow$$ -> →
  text = text.replace(/\$\$\s*\\downarrow\s*\$\$/g, '\n\n↓\n\n');
  text = text.replace(/\$\$\s*\\uparrow\s*\$\$/g, '\n\n↑\n\n');
  text = text.replace(/\$\$\s*(?:\\rightarrow|\\to)\s*\$\$/g, ' → ');
  text = text.replace(/\$\$\s*\\leftarrow\s*\$\$/g, ' ← ');

  // Single $ arrows in prose: $\uparrow$ -> ↑, $\downarrow$ -> ↓, $\rightarrow$ -> →
  text = text.replace(/\$\s*\\downarrow\s*\$/g, '↓');
  text = text.replace(/\$\s*\\uparrow\s*\$/g, '↑');
  text = text.replace(/\$\s*(?:\\rightarrow|\\to)\s*\$/g, '→');
  text = text.replace(/\$\s*\\leftarrow\s*\$/g, '←');

  // Replace raw LaTeX arrows in text
  text = text.replace(/\\downarrow/g, '↓');
  text = text.replace(/\\uparrow/g, '↑');
  text = text.replace(/(?:\\rightarrow|\\to)/g, '→');
  text = text.replace(/\\leftarrow/g, '←');

  // 6. Convert ASCII arrows and heavy arrows to clean Unicode arrows
  text = text.replace(/(?:<--|<-)/g, '←');
  text = text.replace(/(?:-->|->|➔)/g, '→');

  // 7. Bracketed or parenthesized arrow descriptions: e.g. [arrow] or (yields)
  text = text.replace(/\s*\[(?:arrow|yields)\]\s*/gi, ' → ');
  text = text.replace(/\s*\((?:arrow|yields)\)\s*/gi, ' → ');

  // 8. If an explanation process chain contains the words "yields" or "arrow" between terms:
  // Chained yields: e.g., "Sunlight yields Chlorophyll yields Glucose" -> "Sunlight → Chlorophyll → Glucose"
  text = text.replace(/([a-zA-Z0-9]+)\s+yields\s+([a-zA-Z0-9]+)\s+yields\s+([a-zA-Z0-9]+)/gi, '$1 → $2 → $3');
  // Capitalized process terms linked with arrow or yields: "Sunlight yields Chlorophyll" or "Input arrow Output"
  text = text.replace(/\b([A-Z][a-zA-Z0-9_]*)\s+(?:arrow|yields)\s+([A-Z][a-zA-Z0-9_]*)\b/g, '$1 → $2');

  // 9. Clean block math that only wraps \text{...} or step labels:
  // e.g. $$\text{Price Increase } (\uparrow P)$$ -> Price Increase (↑ P)
  // e.g. $$\text{Step 1: Introduction}$$ -> Step 1: Introduction
  text = text.replace(/\$\$\s*\\text\{([^}]+)\}([^$]*)\$\$/g, (_match, textPart, rest) => {
    const combined = `${textPart}${rest}`.trim();
    return `\n\n${combined}\n\n`;
  });

  // Strip standalone \text{...} inside text
  text = text.replace(/\\text\{([^}]+)\}/g, '$1');

  // 10. Protect valid block math ($$...$$) with placeholders
  const mathBlocks: string[] = [];
  text = text.replace(/\$\$([\s\S]+?)\$\$/g, (_match, inner) => {
    if (isValidMath(inner)) {
      mathBlocks.push(`$$${inner.trim()}$$`);
      return `__MATH_BLOCK_${mathBlocks.length - 1}__`;
    }
    // Unwrap plain text
    return inner.trim();
  });

  // 11. Protect valid inline math ($...$) with placeholders
  const inlineMaths: string[] = [];
  text = text.replace(/\$([^\$\n]+?)\$/g, (_match, inner) => {
    if (isValidMath(inner)) {
      inlineMaths.push(`$${inner.trim()}$`);
      return `__INLINE_MATH_${inlineMaths.length - 1}__`;
    }
    // Stray dollar sign around non-math words: unwrap it!
    return inner.trim();
  });

  // 12. Remove any remaining stray/orphan unclosed dollar signs that are not currency
  // (e.g. text containing lone $ without closing $)
  text = text.replace(/\$(?=[^\d\s])/g, '');

  // 13. Restore protected items in reverse order
  text = text.replace(/__INLINE_MATH_(\d+)__/g, (_match, idx) => {
    return inlineMaths[Number(idx)];
  });

  text = text.replace(/__MATH_BLOCK_(\d+)__/g, (_match, idx) => {
    return mathBlocks[Number(idx)];
  });

  text = text.replace(/__CURRENCY_(\d+)__/g, (_match, idx) => {
    return currencies[Number(idx)];
  });

  text = text.replace(/__INLINE_CODE_(\d+)__/g, (_match, idx) => {
    return inlineCodes[Number(idx)];
  });

  text = text.replace(/__CODE_BLOCK_(\d+)__/g, (_match, idx) => {
    return codeBlocks[Number(idx)];
  });

  // 14. Normalize multiple spaces outside code blocks
  text = text.replace(/[ \t]{2,}/g, ' ');

  return text;
}
